// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {PENNY_BY_PENNY} from "../src/PENNY_BY_PENNY.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    PENNY_BY_PENNY c;

    function setUp() public {
        c = new PENNY_BY_PENNY();
    }

    function _run(uint256 lockAdd, uint256 amountPut) internal {
        amountPut = bound(amountPut, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(address(this).balance >= amountPut);
        uint256 beforeUnlock;
        uint256 beforeBalance;
        try c.Acc(address(this)) returns (uint256 __r0, uint256 __r1) { beforeUnlock = __r0; beforeBalance = __r1; } catch { return; }
        uint beforeCbal = address(c).balance;
        bool reverted;
        try c.Put{value: amountPut}(lockAdd) {
            reverted = false;
        } catch {
            reverted = true;
        }
        uint256 afterUnlock;
        uint256 afterBalance;
        try c.Acc(address(this)) returns (uint256 __r0, uint256 __r1) { afterUnlock = __r0; afterBalance = __r1; } catch { return; }
        uint afterCbal = address(c).balance;
        assertTrue((reverted && afterBalance == beforeBalance && afterCbal == beforeCbal)
            ||
            (!reverted && afterBalance >= beforeBalance && afterCbal == beforeCbal + amountPut));
    }

    function testFuzz_run(uint256 lockAdd, uint256 amountPut) public {
        _run(lockAdd, amountPut);
    }

    receive() external payable {}
}
